%%{init: {
  'theme': 'base',
  'themeVariables': {
    'fontFamily': 'system-ui, -apple-system, "Noto Sans SC", "PingFang SC", sans-serif',
    'fontSize': '14px',
    'lineColor': '#6B7280',
    'primaryTextColor': '#212529'
  },
  'flowchart': {
    'nodeSpacing': 24,
    'rankSpacing': 28,
    'curve': 'linear',
    'padding': 12
  }
