flowchart TD
n0("Pretraining: massive general corpus -&gt; base model (general language ability)")
    n1("Finetuning: small domain-specific data -&gt; same model + delta patch")
    n2("Pretraining provides the foundation, finetuning adds specialization")
    n0 --> n1
    n1 --> n2

    classDef neutral fill:#F8FBFF,stroke:#212529,stroke-width:1.5px,color:#212529,rx:6,ry:6;
    classDef root fill:#FCE0E1,stroke:#212529,stroke-width:1.5px,color:#212529,rx:6,ry:6,font-weight:bold;
    classDef category fill:#C2E8F7,stroke:#212529,stroke-width:1.5px,color:#212529,rx:6,ry:6;
    classDef leaf fill:#F3F3F4,stroke:#212529,stroke-width:1.5px,color:#212529,rx:6,ry:6;
    classDef input fill:#FFE2BB,stroke:#212529,stroke-width:1.5px,color:#212529,rx:6,ry:6;
    classDef output fill:#CCE7CF,stroke:#212529,stroke-width:1.5px,color:#212529,rx:6,ry:6;
    classDef warning fill:#F2F4C1,stroke:#212529,stroke-width:1.5px,color:#212529,rx:6,ry:6;
    classDef error fill:#FECACA,stroke:#F87171,stroke-width:1.5px,color:#212529,rx:6,ry:6;

    class n0 input;
    class n2 output;
    class n1 leaf;

    linkStyle default stroke:#6B7280,stroke-width:1.5px;
